/** Curated seed catalogue. Exact SI defining constants are distinguished from measured CODATA values. */
public final class ScientificCatalog {
 private ScientificCatalog() {}
 private static final String NIST="NIST CODATA 2022, Fundamental Physical Constants, https://physics.nist.gov/cuu/Constants/index.html";
 private static final String BIPM="BIPM, The International System of Units (SI), 9th edition, 2019, https://www.bipm.org/en/publications/si-brochure";
 private static Map<String,Object> datum(String id,String name,String category,double value,String unit,String uncertainty,boolean exact,String url,String method,String notes){
  Map<String,Object> m=new LinkedHashMap<>();m.put("id",id);m.put("name",name);m.put("category",category);m.put("value",value);m.put("unit",unit);m.put("uncertainty",uncertainty);m.put("exact",exact);m.put("kind",exact?"SI_DEFINITION":"MEASURED_REFERENCE_VALUE");m.put("source",url.startsWith("https://www.bipm")?BIPM:NIST);m.put("sourceUrl",url);m.put("title",url.startsWith("https://www.bipm")?"The International System of Units (SI), 9th edition":"CODATA 2022 recommended values" );m.put("institution",url.startsWith("https://www.bipm")?"BIPM":"NIST/CODATA");m.put("publicationYear",url.startsWith("https://www.bipm")?2019:2025);m.put("license","Reference data; cite source; no separate database license asserted");m.put("retrievedOn","2026-11-03");m.put("originalUnit",unit);m.put("normalizedUnit",unit);m.put("method",method);m.put("conditions","CODATA recommended value unless exact SI definition");m.put("assumptions",notes);m.put("verification",exact?"VERIFIED_EXACT_SI_DEFINITION":"VERIFIED_CODATA_2022");return m;
 }
 public static List<Map<String,Object>> constants(){String cod="https://physics.nist.gov/cuu/Constants/index.html",si="https://www.bipm.org/en/publications/si-brochure";List<Map<String,Object>> a=new ArrayList<>();
  a.add(datum("c","Speed of light in vacuum","relativity",299792458,"m/s","0 (defined exact)",true,si,"SI defining constant","Exact by definition; vacuum.") );
  a.add(datum("h","Planck constant","quantum",6.62607015e-34,"J s","0 (defined exact)",true,si,"SI defining constant","Exact by definition.") );
  a.add(datum("k_B","Boltzmann constant","thermodynamics",1.380649e-23,"J/K","0 (defined exact)",true,si,"SI defining constant","Exact by definition.") );
  a.add(datum("e","Elementary charge","electromagnetism",1.602176634e-19,"C","0 (defined exact)",true,si,"SI defining constant","Magnitude of elementary charge; exact by definition.") );
  a.add(datum("N_A","Avogadro constant","constants",6.02214076e23,"mol^-1","0 (defined exact)",true,si,"SI defining constant","Exact by definition.") );
  a.add(datum("G","Newtonian constant of gravitation","gravitation",6.67430e-11,"m^3 kg^-1 s^-2","0.00015e-11",false,cod,"CODATA 2022 recommended value","Not exact; uncertainty is standard uncertainty.") );
  a.add(datum("m_e","Electron mass","particle masses",9.1093837139e-31,"kg","0.0000000028e-31",false,cod,"CODATA 2022 recommended value","Rest mass.") );
  a.add(datum("m_p","Proton mass","particle masses",1.67262192595e-27,"kg","0.00000000052e-27",false,cod,"CODATA 2022 recommended value","Rest mass.") );
  a.add(datum("m_n","Neutron mass","particle masses",1.67492750056e-27,"kg","0.00000000085e-27",false,cod,"CODATA 2022 recommended value","Rest mass.") );
  a.add(datum("epsilon_0","Vacuum electric permittivity","electromagnetism",8.8541878188e-12,"F/m","0.0000000014e-12",false,cod,"CODATA 2022 recommended value","Measured/recommended value in post-2019 SI.") );
  a.add(datum("mu_0","Vacuum magnetic permeability","electromagnetism",1.25663706127e-6,"N/A^2","0.00000000020e-6",false,cod,"CODATA 2022 recommended value","Measured/recommended value in post-2019 SI.") );
  a.add(datum("sigma_SB","Stefan-Boltzmann constant","thermodynamics",5.670374419e-8,"W m^-2 K^-4","0 (derived from exact constants)",true,cod,"Derived from exact defining constants","Exact in current SI from k_B, h and c.") );
  a.add(datum("g0","Standard gravity","units",9.80665,"m/s^2","0 (conventional value)",true,cod,"Conventional standard value","Defined conventional value; not local measured gravity.") );
  a.add(datum("au","Astronomical unit","astronomy",149597870700d,"m","0 (defined exact)",true,"https://www.iau.org/static/resolutions/IAU2012_English.pdf","IAU 2012 Resolution B2","Exact definition; not an instantaneous Earth-Sun distance.") );
  return List.copyOf(a);
 }
 public static double value(String id){return constants().stream().filter(x->x.get("id").equals(id)).map(x->((Number)x.get("value")).doubleValue()).findFirst().orElseThrow(()->new IllegalArgumentException("constant not found: "+id));}
 public static List<Map<String,Object>> equations(){List<Map<String,Object>> out=new ArrayList<>();String[][] rows={
  {"rocket-ideal","Ideal rocket equation","Δv = ve ln(m0/mf)","Δv: m/s; ve: m/s; m0,mf: kg","Constant effective exhaust velocity; no external forces","Idealized single-stage performance only","NASA Glenn, Ideal Rocket Equation","https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/ideal-rocket-equation/","propulsion"},
  {"photon-thrust","Photon thrust","F = P/c","F: N; P: W; c: m/s","Directed photon beam; ideal absorption/emission","Does not include source mass, efficiency or thermal design","NASA Glenn, Thrust Equation","https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/thrust-equation/","propulsion"},
  {"newton-second","Newton's second law","F = ma","F: N; m: kg; a: m/s²","Inertial frame; constant mass form","Variable-mass propulsion requires momentum-flow terms","OpenStax University Physics Vol. 1","https://openstax.org/books/university-physics-volume-1/pages/5-4-newtons-second-law","mechanics"},
  {"kinetic-energy","Kinetic energy","K = ½mv²","K: J; m: kg; v: m/s","Classical speeds, v much less than c","Use relativistic energy at high speed","OpenStax University Physics Vol. 1","https://openstax.org/books/university-physics-volume-1/pages/7-2-kinetic-energy","mechanics"},
  {"first-law","First law, closed system","ΔU = Q − W","U,Q,W: J","Sign convention: W done by system","Requires defined boundary and sign convention","OpenStax University Physics Vol. 2","https://openstax.org/books/university-physics-volume-2/pages/3-4-the-first-law-of-thermodynamics","thermodynamics"},
  {"fourier","Fourier conduction, 1D steady","Qdot = kAΔT/L","Qdot: W; k: W/(m K); A: m²; ΔT: K; L: m","Steady one-dimensional conduction; constant k","Contact resistance and transient effects omitted","OpenStax University Physics Vol. 2","https://openstax.org/books/university-physics-volume-2/pages/1-6-mechanisms-of-heat-transfer","heat transfer"},
  {"lorentz-force","Lorentz force","F = q(E + v × B)","F: N; q: C; E: V/m; v: m/s; B: T","Classical fields and particle velocity","Radiation reaction omitted","OpenStax University Physics Vol. 2","https://openstax.org/books/university-physics-volume-2/pages/11-4-magnetic-force-on-a-current-carrying-conductor","electromagnetism"},
  {"mass-energy","Relativistic energy-momentum","E² = (pc)² + (mc²)²","E: J; p: kg m/s; m: kg","Special relativity in inertial frame","Invariant relation; does not specify dynamics","OpenStax University Physics Vol. 3","https://openstax.org/books/university-physics-volume-3/pages/5-key-equations","special relativity"},
  {"lorentz-factor","Lorentz factor","γ = 1/sqrt(1 − v²/c²)","γ: dimensionless; v,c: m/s","|v| < c in inertial frame","Singular at light speed for massive objects","OpenStax University Physics Vol. 3","https://openstax.org/books/university-physics-volume-3/pages/5-key-equations","special relativity"},
  {"einstein-field","Einstein field equation","Gμν + Λgμν = (8πG/c⁴)Tμν","Tensor equation; conventions and units depend on coordinates","General relativity; stated metric/signature convention required","Numerical solution and physical source require separate validation","Einstein, Die Grundlage der allgemeinen Relativitätstheorie (1916)","https://doi.org/10.1002/andp.19163540702","general relativity"},
  {"schwarzschild","Schwarzschild exterior metric","ds² = −(1−rs/r)c²dt² + (1−rs/r)⁻¹dr² + r²dΩ²","rs,r: m; t: s; angular coordinates dimensionless","Spherical, static vacuum exterior; r > rs","Not a rotating body; coordinate singularity at horizon","Schwarzschild (1916), archived translation","https://arxiv.org/abs/physics/9905030","general relativity"},
  {"alcubierre","Alcubierre metric (original proposal)","ds² = −c²dt² + [dx − v_s f(r_s)dt]² + dy² + dz²","Coordinates: m and s; v_s: m/s; f dimensionless","Specific prescribed spacetime geometry","Theoretical metric; source requirements and physical realizability unresolved","Alcubierre (1994), Class. Quantum Grav. 11, L73","https://doi.org/10.1088/0264-9381/11/5/001","general relativity"},
  {"morris-thorne","Morris–Thorne wormhole metric","ds² = −e^(2Φ)c²dt² + (1−b/r)⁻¹dr² + r²dΩ²","r,b: m; Φ dimensionless; t: s","Static, spherically symmetric traversable-wormhole ansatz","Requires throat/energy-condition analysis; not evidence of realizable wormholes","Morris & Thorne (1988), Am. J. Phys. 56, 395","https://doi.org/10.1119/1.15620","general relativity"},
  {"simpson","Composite Simpson integration","∫aᵇf(x)dx ≈ h/3 [f0 + 4f1 + 2f2 + … + fn]","Units are f·x; h=(b−a)/n","Smooth integrand; even number of subintervals","Error depends on fourth derivative and mesh","NIST DLMF §3","https://dlmf.nist.gov/3","numerical methods"},
  {"rk4","Classical fourth-order Runge–Kutta","yₙ₊₁ = yₙ + h(k₁+2k₂+2k₃+k₄)/6","Units follow ODE state y and independent variable","Initial-value ODE; fixed step","Local/global error depend on smoothness and step size","NIST DLMF §3","https://dlmf.nist.gov/3","numerical methods"}
 };for(String[]r:rows){Map<String,Object>m=new LinkedHashMap<>();m.put("id",r[0]);m.put("name",r[1]);m.put("equation",r[2]);m.put("description","Model/equation reference; use stated domain and assumptions.");m.put("variablesAndUnits",r[3]);m.put("domain",r[8]);m.put("assumptions",r[4]);m.put("validityLimits",r[5]);m.put("sourceTitle",r[6]);m.put("source",r[6]);m.put("authorOrInstitution",r[6].split(",")[0]);Integer year=r[0].equals("einstein-field")?Integer.valueOf(1916):r[0].equals("alcubierre")?Integer.valueOf(1994):r[0].equals("morris-thorne")?Integer.valueOf(1988):null;m.put("publicationYear",year);m.put("doiOrUrl",r[7]);m.put("license","Bibliographic metadata; consult source terms");m.put("retrievedOn","2026-11-03");m.put("verification","SOURCE_LINKED_REFERENCE");out.add(m);}return List.copyOf(out);}
 public static Map<String,Object> validate(){List<String> errors=new ArrayList<>(),warnings=new ArrayList<>();Map<String,String> expectedUnits=Map.ofEntries(Map.entry("c","m/s"),Map.entry("h","J s"),Map.entry("k_B","J/K"),Map.entry("e","C"),Map.entry("N_A","mol^-1"),Map.entry("G","m^3 kg^-1 s^-2"),Map.entry("m_e","kg"),Map.entry("m_p","kg"),Map.entry("m_n","kg"),Map.entry("epsilon_0","F/m"),Map.entry("mu_0","N/A^2"),Map.entry("sigma_SB","W m^-2 K^-4"),Map.entry("g0","m/s^2"),Map.entry("au","m"));Set<String>ids=new HashSet<>();for(Map<String,Object> c:constants()){String id=Objects.toString(c.get("id"),"");if(!ids.add("constant:"+id))errors.add("duplicate constant id: "+id);if(!(c.get("value") instanceof Number n)||!Double.isFinite(n.doubleValue())||n.doubleValue()<=0)errors.add("invalid constant value: "+id);if(Objects.toString(c.get("unit"),"").isBlank())errors.add("missing unit: "+id);else if(!Objects.toString(c.get("unit"),"").equals(expectedUnits.get(id)))errors.add("unit mismatch: "+id);if(!Boolean.TRUE.equals(c.get("exact"))&&Objects.toString(c.get("uncertainty"),"").isBlank())errors.add("missing uncertainty: "+id);if(Objects.toString(c.get("sourceUrl"),"").isBlank()||Objects.toString(c.get("verification"),"").isBlank())errors.add("missing provenance: "+id);if(Boolean.TRUE.equals(c.get("exact"))&&!Objects.toString(c.get("uncertainty"),"").startsWith("0"))errors.add("exact constant has nonzero/unknown uncertainty: "+id);}Set<String>eqids=new HashSet<>();for(Map<String,Object> e:equations()){String id=Objects.toString(e.get("id"),"");if(!eqids.add(id))errors.add("duplicate equation id: "+id);for(String k:List.of("equation","variablesAndUnits","domain","assumptions","validityLimits","sourceTitle","doiOrUrl","verification"))if(Objects.toString(e.get(k),"").isBlank())errors.add("incomplete equation "+id+": "+k);if(!Objects.toString(e.get("doiOrUrl"),"").startsWith("https://"))errors.add("invalid equation source link: "+id);}List<MaterialDatabase.Material> materials=new MaterialDatabase(DataPaths.path("data","materials.jsonl")).all();for(var m:materials){if(m.id()==null||m.id().isBlank())errors.add("material id missing");if(m.source()==null||m.source().isBlank())errors.add("material source missing: "+m.name());for(Double v:new Double[]{m.densityKgM3(),m.yieldPa(),m.tensilePa(),m.youngPa(),m.conductivityWmK(),m.specificHeatJkgK(),m.meltingK(),m.expansionPerK()})if(v!=null&&(!Double.isFinite(v)||v<0))errors.add("invalid material property: "+m.name());if(m.yieldPa()==null||m.tensilePa()==null)warnings.add("UNKNOWN allowable strength: "+m.name());if(m.verification().contains("unknown"))warnings.add("traceability warning: "+m.name());}Path expPath=DataPaths.path("data","published_experiments.jsonl");int experiments=0;try{if(Files.exists(expPath))for(String line:Files.readAllLines(expPath)){if(line.isBlank())continue;experiments++;Map<String,Object> e=Json.map(Json.parse(line));for(String k:List.of("id","kind","title","institution","year","source","method","conditions","units","uncertainty","limits","verification"))if(Objects.toString(e.get(k),"").isBlank())errors.add("published experiment missing "+k+": "+e.get("id"));if(!Objects.toString(e.get("source"),"").startsWith("https://"))errors.add("invalid published experiment source: "+e.get("id"));}}catch(Exception ex){errors.add("published experiment catalog unreadable: "+ex.getMessage());}Path curvePath=DataPaths.path("data","material_curves.jsonl");int curveCount=0;Set<String> curveIds=new HashSet<>();try{if(Files.exists(curvePath))for(String line:Files.readAllLines(curvePath)){if(line.isBlank())continue;curveCount++;Map<String,Object> c=Json.map(Json.parse(line));String id=Objects.toString(c.get("id"),"");if(id.isBlank()||!curveIds.add(id))errors.add("material curve id missing or duplicate: "+id);for(String k:List.of("materialId","property","propertyUnit","kind","source","conditions","uncertainty","limitations","evidenceType"))if(c.get(k)==null||Objects.toString(c.get(k),"").isBlank())errors.add("material curve incomplete "+id+": "+k);if(!Objects.toString(c.get("source"),"").contains("https://"))errors.add("material curve source missing: "+id);if(Objects.toString(c.get("kind"),"").equals("POINTS_LINEAR")&&!Objects.toString(c.get("axis"),"temperature").equals("temperature")){if(!(c.get("xMin") instanceof Number)||!(c.get("xMax") instanceof Number))errors.add("point curve x range missing: "+id);else if(((Number)c.get("xMin")).doubleValue()>=((Number)c.get("xMax")).doubleValue())errors.add("invalid material curve x range: "+id);}else if(c.get("dataMinK") instanceof Number lo&&c.get("dataMaxK") instanceof Number hi){if(lo.doubleValue()>=hi.doubleValue())errors.add("invalid material curve range: "+id);}else errors.add("material curve temperature range missing: "+id);if(c.get("kind") instanceof String kind&&kind.startsWith("NIST_")&&(!(c.get("coefficients") instanceof List<?> co)||co.isEmpty()))errors.add("NIST fit coefficients missing: "+id);}}catch(Exception ex){errors.add("material curve archive unreadable: "+ex.getMessage());}Map<String,Object> result=new LinkedHashMap<>();result.put("status",errors.isEmpty()?"PASS":"FAIL");result.put("publishedExperimentsChecked",experiments);result.put("materialCurvesChecked",curveCount);result.put("constantsChecked",constants().size());result.put("equationsChecked",equations().size());result.put("materialsChecked",materials.size());result.put("errors",errors);result.put("warnings",warnings);result.put("duplicateIds",List.of());result.put("unitPolicy","Native source units are retained; normalized unit equals source unit. No silent conversion.");result.put("sourceConflicts","No duplicate-source conflict found in the curated seed set; independent values are not reconciled automatically.");return result;}
 public static Map<String,Object> materialRecord(MaterialDatabase.Material m){Map<String,Object> r=Main.recordMap(m);boolean nasaTable=m.id().startsWith("al-");boolean nist=m.id().contains("nist");r.put("sourceTitle",nasaTable?"NASA, State of the Art: Small Spacecraft Technology (2014), Table 29":nist?"NIST Cryogenic Material Properties Database":m.source());r.put("authorOrInstitution",nasaTable?"NASA":nist?"NIST":m.id().equals("ti64-nasa")?"NASA":"NASA Ames (legacy TPSX record; traceability marked unknown)");r.put("publicationYear",nasaTable?Integer.valueOf(2014):m.id().equals("ti64-nasa")?Integer.valueOf(2020):null);r.put("doiOrUrl",m.source().contains("http")?m.source().substring(m.source().lastIndexOf("http")):"");r.put("license","UNKNOWN; consult source handbook/database terms");r.put("retrievedOn","2026-11-03");r.put("originalUnits",nasaTable?"NASA Table 29 units: density g/cm³, modulus GPa, tensile strength MPa, thermal conductivity W/(m K), resistivity Ω·cm. Missing properties not reported.":nist?"Scalar values not transcribed; individual NIST curve-fit records retain property-specific units and ranges.":m.id().equals("ti64-nasa")?"Legacy record: specific heat source was J/g-K and converted; other property-specific source units were not preserved.":"Legacy TPSX record; original units were not preserved field by field; see cited source record.");r.put("normalizedUnits",nasaTable?"SI fields; density ×1000 kg/m³ per g/cm³, modulus ×10^9 Pa per GPa, tensile ×10^6 Pa per MPa, resistivity ×10^-2 Ω·m per Ω·cm.":"SI property fields; curve fit units remain as stated by NIST; no query-time unit conversion.");r.put("method",m.conditions());r.put("assumptions","Grade/composition and test conditions apply only as stated; null values are UNKNOWN.");return r;}
 public static Map<String,Object> all(){Map<String,Object> r=new LinkedHashMap<>();r.put("constants",constants());r.put("equations",equations());r.put("materials",new MaterialDatabase(DataPaths.path("data","materials.jsonl")).all().stream().map(ScientificCatalog::materialRecord).toList());try{Path p=DataPaths.path("data","published_experiments.jsonl");r.put("publishedExperiments",Files.exists(p)?Files.readAllLines(p).stream().filter(x->!x.isBlank()).map(x->Json.map(Json.parse(x))).toList():List.of());}catch(Exception e){r.put("publishedExperiments",List.of());}r.put("materialCurves",new MaterialCurveDatabase(DataPaths.path("data","material_curves.jsonl")).all());r.put("categories",List.of("constants","relativity","thermodynamics","electromagnetism","astronomy","units","mechanics","propulsion","materials","published experiments","numerical methods"));r.put("validation",validate());return r;}
}
